#define AUF_LANG_FRE
// The mouse looks on foot as in a PC shooter: its movement turns the client's angles directly, not through the stick.
//
// The input layer 0x24570 (cmd, player) keeps degrees per player at 0x2A8124 (pitch) and 0x2A8128 (yaw), stride 0x30, and
// turns them by the stick times the rates 0x2A8144 (yaw) and 0x2A8148 (pitch): 0.5/zoom through a scope, 0.33 and 0.66 in
// manual aim, 0 when the player has no control (a cutscene, a frozen player), so the mouse follows them too. Yaw grows to
// the left, pitch downwards. The server clamps pitch (0xC46E0). The console's invert option is the byte 0x3B22D5.
// Headless (no mouse): AUF_MOUSE_TEST=dx,dy,from,to plays that many counts a call for calls from..to.
#include "bond/addr.h"
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#include "common/auf.h"
#include "core/input.h"
#include "core/log.h"
#include "kernel/kernel.h"
#include "xdk/hle.h"

namespace {
constexpr uint32_t kPitch = A(0x2A8124), kYaw = A(0x2A8128), kYawRate = A(0x2A8144), kPitchRate = A(0x2A8148), kInvert = A(0x3B22D5);
constexpr float kDegreesPerCount = 0.0458f;  // at 100% sensitivity: 36 degrees an inch at 800 counts an inch

float GetF(uint32_t va) {
    float f;
    std::memcpy(&f, &kernel::G<uint32_t>(va), 4);
    return f;
}
void SetF(uint32_t va, float f) { std::memcpy(&kernel::G<uint32_t>(va), &f, 4); }

// the mouse's counts since the last call, times the sensitivity
bool Counts(float& x, float& y) {
    static const struct Test {
        float dx = 0, dy = 0;
        uint32_t from = 0, to = 0;
    } test = [] {
        Test t;
        if (const char* e = std::getenv("AUF_MOUSE_TEST")) std::sscanf(e, "%f,%f,%u,%u", &t.dx, &t.dy, &t.from, &t.to);
        return t;
    }();
    static uint32_t call = 0;
    call++;
    if (test.to) {
        bool on = call >= test.from && call <= test.to;
        x = on ? test.dx : 0, y = on ? test.dy : 0;
        return true;
    }
    static auto last = std::chrono::steady_clock::now();
    auto now = std::chrono::steady_clock::now();
    float dt = std::clamp(std::chrono::duration<float>(now - last).count(), 0.001f, 0.1f);
    last = now;
    if (!input::UsingKeyboard() || !input::TakeMouse(x, y)) return false;  // a controller in use: its own stick
    x *= 2400 * dt, y *= 2400 * dt;  // TakeMouse's rate (2400 counts a second at 100% is 1) back to counts
    return true;
}
}  // namespace

X86_EXTERN_FUNC(__imp__sub_00024570);
X86_FUNC(sub_00024570) {
    float x, y;
    if (kernel::R32(ctx.esp + 8) == 0 && Counts(x, y)) {
        float rx = GetF(kYawRate), ry = GetF(kPitchRate);
        bool invert = kernel::G<uint8_t>(kInvert) != 0;
        SetF(kYaw, GetF(kYaw) - x * kDegreesPerCount * rx);
        // Harry on Windows: through the sniper's scope (end of mission 1) up and down come out inverted. Not found in the code: the rate's
        // sign is the same (0xB4659). Flipped there by his report
        if (auf::Zoomed()) y = -y;
        SetF(kPitch, GetF(kPitch) + (invert ? -y : y) * kDegreesPerCount * ry);
        static bool said = false;
        if (!said && (x || y) && rx != 0) {
            said = true;
            LOGR("auf: the mouse turns the view directly");
        }
    }
    __imp__sub_00024570(ctx, base);
}

// The wheel through a scope: a weapon's zoom is its +0x51C, read each frame at 0xBD768 (esi the weapon, only when +0x52C says it
// zooms) into the player's view; its most is +0x524, and leaving the scope is the game's own. The wheel's notches, counted on the
// input thread, multiply it here, on the game's. Zoomed: the player state's +0x2E4, 1 when not.
namespace {
std::atomic<int> g_zoom_notches{0};
constexpr float kNotchStep = 1.25f;
}  // namespace

namespace auf {
// the input layer's rate: 0 when the player has no control (0xB45C0, 0xAEDC0)
bool PlayerFree() { return GetF(kYawRate) != 0; }
bool Zoomed() {
    uint32_t ps = kernel::R32(A(0x2A88B8));
    return ps && GetF(ps + 0x2E4) > 1.01f;
}
void ScopeZoom(int notches) { g_zoom_notches += notches; }
}  // namespace auf

void WheelZoom(X86Context& ctx, uint8_t*) {
    int notches = g_zoom_notches.exchange(0);
    if (!notches) return;
    float most = GetF(ctx.esi + 0x524);
    if (!(most > 1.0f)) return;
    SetF(ctx.esi + 0x51C, std::clamp(GetF(ctx.esi + 0x51C) * std::pow(kNotchStep, float(notches)), 1.0f, most));
}

// Auto-aim: the target search 0xB8BB0 (fastcall: the player) only looks for a target when the player's +0x716 is set (the game's
// option, written at 0xBA8AC, 0xDEC4D, 0xF4426). Off, it sees that clear for the call, and the option stays as set.
X86_EXTERN_FUNC(__imp__sub_000B8AC0);
X86_FUNC(sub_000B8AC0) {
    const uint32_t player = ctx.ecx;
    if (auf::auto_aim || !player) return __imp__sub_000B8AC0(ctx, base);
    uint8_t& flag = kernel::G<uint8_t>(player + 0x716);
    const uint8_t was = flag;
    static bool said = false;
    if (!said && was) {
        said = true;
        LOGR("auf: auto-aim off (the game's option was on)");
    }
    flag = 0;
    __imp__sub_000B8AC0(ctx, base);
    flag = was;
}
